                  <span className="bg-brand-blue-100 text-brand-blue-700 px-2 py-1 rounded-full">{vacancy.experienceLevel}</span>
              </div>
          </div>
          <p className="mt-4 text-brand-blue-900/90 font-lato flex-grow line-clamp-3">{vacancy.description}</p>
          <button onClick={() => onApply(vacancy)} className="mt-6 bg-brand-blue-500 hover:bg-brand-blue-600 text-white font-bold py-2 px-4 rounded-md transition-colors duration-300 font-roboto-condensed self-start">
            {t('vacancyPage.applyNow')}
          </button>
        </div>
    );

    return (
        <>
            <AnimatedSection>
                <div className="bg-brand-blue-800 p-4 rounded-md mb-12 grid grid-cols-1 md:grid-cols-4 gap-4 items-center">
                    <h3 className="text-lg font-bold text-white font-roboto-condensed md:text-right">{t('vacancyPage.filterBy')}</h3>
                    <select name="role" value={filters.role} onChange={handleFilterChange} className="bg-brand-blue-900 border border-brand-blue-700 text-white text-sm rounded-md focus:ring-brand-blue-500 focus:border-brand-blue-500 w-full p-2">
                        {filterOptions.roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                    <select name="division" value={filters.division} onChange={handleFilterChange} className="bg-brand-blue-900 border border-brand-blue-700 text-white text-sm rounded-md focus:ring-brand-blue-500 focus:border-brand-blue-500 w-full p-2">
