        try {
            // Check if we are updating (editingIndustry was set and has ID) OR create (if user provided an ID)
            const isUpdate = industries.some(ind => ind.id === industry.id);

            if (isUpdate && industry.id) {
                await updateIndustry(industry.id, industry);
                addToast('Industry updated successfully', 'success');
            } else {
                await createIndustry(industry);
                addToast('Industry created successfully', 'success');
            }
            fetchIndustries();
            setIsModalOpen(false);
            setEditingIndustry(null);
        } catch (error) {
            addToast('Failed to save industry.', 'error');
        }
    };

    const handleOpenModal = (industry?: Industry) => {
        setEditingIndustry(industry || null);
        setIsModalOpen(true);
    };

    return (
        <>
            {isModalOpen && <IndustryFormModal industry={editingIndustry} onClose={() => setIsModalOpen(false)} onSave={handleSave} />}
            <Card title="Industry Divisions Management" className="shadow-lg">
                <div className="mb-6 flex flex-col md:flex-row justify-between items-center gap-4">
                    <div>
                        <p className="text-gray-500">Manage detailed profiles for all industrial engineering groups.</p>
                        <div className="text-sm text-gray-400 mt-1">Total Divisions: {industries.length}</div>
                    </div>
                    <Button variant="primary" onClick={() => handleOpenModal()}>
                        <span className="mr-2">+</span> New Division
                    </Button>
                </div>

                {loading ? <div className="text-center p-8">Loading Divisions...</div> : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {industries.map(industry => (
                        <div key={industry.id} className="bg-white rounded-lg border border-gray-200 shadow-sm hover:shadow-md transition-all duration-300 flex flex-col overflow-hidden group">
                            <div className="h-24 bg-[#1172BA] relative">
                                <div className="absolute inset-0 bg-black/10"></div>
                                <div className="absolute -bottom-6 left-6 w-16 h-16 bg-white rounded-md shadow-md flex items-center justify-center p-1">
                                    {/* Placeholder Logo */}
                                    <div className="text-[#1172BA] font-black text-xs text-center">{industry.acronym}</div>
                                </div>
                                <div className="absolute top-4 right-4">
                                    <Tag status={industry.status} />
                                </div>
                            </div>
                            <div className="p-6 pt-10 flex-1 flex flex-col">
                                <h3 className="text-lg font-bold text-[#1E2B2B]">{industry.name}</h3>
                                <p className="text-xs text-gray-500 uppercase tracking-wide font-semibold mt-1">{industry.acronym}</p>
                                <p className="text-sm text-gray-600 mt-3 line-clamp-2">{industry.description}</p>

                                <div className="mt-auto pt-6 flex justify-end">
                                    <button 
                                        onClick={() => handleOpenModal(industry)}
                                        className="text-[#1172BA] hover:text-[#0E62A1] text-sm font-semibold flex items-center"
                                    >
                                        Manage Details <span className="ml-1 text-lg">→</span>
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
                )}
            </Card>
        </>
    );
};

export default IndustryManagement;

import '../../../types';
import React, { useState, useEffect } from 'react';
import { getVacancies, createVacancy, updateVacancy, deleteVacancy } from '../../../services/api';
import Card from '../ui/Card';
import Table from '../ui/Table';
import Button from '../ui/Button';
import Tag from '../ui/Tag';
import TagInput from '../ui/TagInput';
import ApplicantTracker from './ApplicantTracker';
import type { Vacancy, VacancyStatus, Division } from '../../../types';
import { useToast } from '../../../App';

const VacancyFormModal: React.FC<{
    vacancy: Partial<Vacancy> | null;
    onClose: () => void;
    onSave: (vacancy: Partial<Vacancy>) => void;
}> = ({ vacancy, onClose, onSave }) => {
    const [formData, setFormData] = useState(vacancy || { requirements: [], responsibilities: [] });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleTagsChange = (key: 'requirements' | 'responsibilities', tags: string[]) => {
        setFormData({ ...formData, [key]: tags });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(formData);
    };

    return (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in">
            <div className="bg-white rounded-lg shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh]">
                <div className="p-6 border-b bg-gray-50 rounded-t-lg">
                    <h3 className="text-xl font-bold font-montserrat text-[#1E2B2B]">{vacancy?.id ? 'Edit Vacancy' : 'Post New Vacancy'}</h3>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-6 overflow-y-auto flex-1">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="md:col-span-2">
                            <label className="block text-sm font-medium text-gray-700 mb-1">Job Title</label>
                            <input name="title" value={formData.title || ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA]" required placeholder="e.g. Senior Mechanical Engineer" />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Department / Division</label>
                            <select name="division" value={formData.division || ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA]" required>
                                <option value="">Select Division</option>
                                <option value="HAEI">HAEI</option>
                                <option value="GAEI">GAEI</option>
                                <option value="BVEIG">BVEIG</option>
                                <option value="LEEIG">LEEIG</option>
                                <option value="Corporate">Corporate</option>
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Employment Type</label>
                            <select name="type" value={formData.type || ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA]" required>
                                <option value="">Select Type</option>
                                <option value="Full-time">Full-time</option>
                                <option value="Part-time">Part-time</option>
                                <option value="Contract">Contract</option>
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Location</label>
                            <input name="location" value={formData.location || ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA]" required placeholder="City, Region" />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Closing Date</label>
                            <input type="date" name="closingDate" value={formData.closingDate ? (typeof formData.closingDate === 'string' ? formData.closingDate.split('T')[0] : new Date(formData.closingDate).toISOString().split('T')[0]) : ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA]" required />
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Job Overview</label>
                        <textarea name="description" value={formData.description || ''} onChange={handleChange} rows={3} className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA]" placeholder="Brief summary of the role..." required />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <TagInput 
                                label="Key Responsibilities" 
                                tags={formData.responsibilities || []} 
                                onChange={(tags) => handleTagsChange('responsibilities', tags)}
                                placeholder="Add responsibility and press Enter"
                            />
                        </div>
                        <div>
                            <TagInput 
                                label="Requirements & Qualifications" 
                                tags={formData.requirements || []} 
                                onChange={(tags) => handleTagsChange('requirements', tags)}
                                placeholder="Add requirement and press Enter"
                            />
                        </div>
                    </div>
                </form>

                <div className="p-4 bg-gray-50 flex justify-end gap-3 border-t rounded-b-lg">
                    <Button type="button" variant="secondary" onClick={onClose}>Cancel</Button>
                    <Button type="submit" variant="primary" onClick={handleSubmit}>Publish Vacancy</Button>
                </div>
            </div>
        </div>
    );
};

const VacancyManagement: React.FC = () => {
    const [vacancies, setVacancies] = useState<Vacancy[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedVacancy, setSelectedVacancy] = useState<Vacancy | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingVacancy, setEditingVacancy] = useState<Partial<Vacancy> | null>(null);
    const { addToast } = useToast();
    const [filters, setFilters] = useState<{
        division: Division | 'All';
        status: VacancyStatus | 'All';
    }>({ division: 'All', status: 'All' });

    const fetchVacancies = async () => {
        try {
            setLoading(true);
            const data = await getVacancies();
            setVacancies(data);
        } catch (err) {
            addToast('Failed to load data', 'error');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchVacancies();
    }, []);

    const handleSave = async (vacancy: Partial<Vacancy>) => {
        try {
            if (vacancy.id) {
                await updateVacancy(vacancy.id, vacancy);
                addToast('Vacancy updated successfully', 'success');
            } else {
                await createVacancy(vacancy);
                addToast('Vacancy created successfully', 'success');
            }
            fetchVacancies();
            setIsModalOpen(false);
            setEditingVacancy(null);
        } catch (error) {
            addToast('Failed to save vacancy.', 'error');
        }
    };

    const handleDelete = async (id: string) => {
        if (window.confirm('Delete this vacancy?')) {
            try {
                await deleteVacancy(id);
                addToast('Vacancy deleted', 'success');
                fetchVacancies();
            } catch (error) { addToast('Error deleting', 'error'); }
        }
    };

    const handleOpenModal = (vacancy?: Vacancy) => {
        setEditingVacancy(vacancy || {});
        setIsModalOpen(true);
    };

    if (selectedVacancy) {
        return <ApplicantTracker vacancy={selectedVacancy} onBack={() => setSelectedVacancy(null)} />;
    }

    const filteredVacancies = vacancies.filter(v => 
        (filters.division === 'All' || v.division === filters.division) &&
        (filters.status === 'All' || v.status === filters.status)
    );

    const tableHeaders = ['Job Title', 'Division', 'Applicants', 'Status', 'Deadline', 'Actions'];

    return (
        <>
        {isModalOpen && <VacancyFormModal vacancy={editingVacancy} onClose={() => setIsModalOpen(false)} onSave={handleSave} />}
        <Card>
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-xl text-[#1E2B2B] font-montserrat font-bold">Recruitment Portal</h2>
                <div className="flex items-center gap-2">
                    <Button variant="primary" onClick={() => handleOpenModal()}>+ Post Job</Button>
                </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-md mb-6 border border-gray-200 grid grid-cols-1 md:grid-cols-3 gap-4">
                 <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">Filter Division</label>
                    <select className="w-full mt-1 border-gray-300 rounded-md text-sm" value={filters.division} onChange={e => setFilters({...filters, division: e.target.value as any})}>
                        <option value="All">All Divisions</option>
                        <option value="HAEI">HAEI</option>
                        <option value="GAEI">GAEI</option>
                        <option value="Corporate">Corporate</option>
                    </select>
                 </div>
                 <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">Filter Status</label>
                    <select className="w-full mt-1 border-gray-300 rounded-md text-sm" value={filters.status} onChange={e => setFilters({...filters, status: e.target.value as any})}>
                        <option value="All">All Statuses</option>
                        <option value="Open">Open</option>
                        <option value="Closed">Closed</option>
                    </select>
                 </div>
            </div>

            <Table headers={tableHeaders}>
                {loading && <tr><td colSpan={6} className="text-center p-8 text-gray-500">Loading vacancies...</td></tr>}
                {!loading && filteredVacancies.map(vacancy => (
                    <tr key={vacancy.id} className="odd:bg-white even:bg-[#effefb] hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4">
                            <div className="font-semibold text-[#1E2B2B]">{vacancy.title}</div>
                            <div className="text-xs text-gray-500">{vacancy.location}</div>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600">{vacancy.division}</td>
                        <td className="px-6 py-4 text-center">
                            <span className="inline-flex items-center justify-center px-2 py-1 text-xs font-bold leading-none text-white bg-[#1172BA] rounded-full">
                                {vacancy.applicantCount}
                            </span>
                        </td>
                        <td className="px-6 py-4"><Tag status={vacancy.status as any} /></td>
                        <td className="px-6 py-4 text-sm text-gray-500 font-mono">{new Date(vacancy.closingDate).toLocaleDateString()}</td>
                        <td className="px-6 py-4 text-right">
                            <div className="flex items-center justify-end gap-2">
                                <Button variant="secondary" size="sm" onClick={() => setSelectedVacancy(vacancy)}>Applicants</Button>
                                <Button variant="icon" size="sm" onClick={() => handleOpenModal(vacancy)}>
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                                </Button>
                                <Button variant="icon" size="sm" className="!text-red-500" onClick={() => handleDelete(vacancy.id)}>
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                </Button>
                            </div>
                        </td>
                    </tr>
                ))}
            </Table>
        </Card>
        </>
    );
};

export default VacancyManagement;

// FIX: Reordered imports to ensure global JSX namespace augmentation from `types.ts` is applied before React is imported. This resolves errors where standard HTML elements were not recognized in JSX.
import '../../../types';
import React, { useState, useEffect } from 'react';
import { getApplicantsByVacancy, updateApplicantStatus } from '../../../services/api';
import type { Vacancy, Applicant, ApplicantStatus } from '../../../types';
import Card from '../ui/Card';
import Table from '../ui/Table';
import Button from '../ui/Button';
import StarRating from '../ui/StarRating';
import { useToast } from '../../../App';

interface ApplicantTrackerProps {
    vacancy: Vacancy;
    onBack: () => void;
}

const DocumentPreviewModal: React.FC<{ url: string; title: string; onClose: () => void }> = ({ url, title, onClose }) => {
    // Check if it's an image
    const isImage = url.match(/\.(jpeg|jpg|gif|png)$/i) || url.startsWith('data:image');

    return (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 backdrop-blur-sm animate-fade-in" onClick={onClose}>
            <div className="bg-white w-full max-w-5xl h-[90vh] rounded-lg flex flex-col shadow-2xl" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center p-4 border-b border-gray-200 bg-gray-50 rounded-t-lg">
                    <div>
                        <h3 className="text-lg font-bold text-[#1E2B2B]">{title}</h3>
                        <p className="text-xs text-gray-500">Document Preview</p>
                    </div>
                    <div className="flex gap-2">
                        {url && url !== '#' && (
                            <a 
                                href={url} 
                                target="_blank"
                                rel="noreferrer"
                                className="px-3 py-1.5 bg-[#1172BA] text-white text-sm font-semibold rounded hover:bg-[#0E62A1] transition-colors flex items-center gap-2"
                            >
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"></path></svg>
                                Open in New Tab
                            </a>
                        )}
                        <button onClick={onClose} className="p-2 text-gray-500 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                        </button>
                    </div>
                </div>
                <div className="flex-1 bg-gray-100 p-4 overflow-hidden relative flex justify-center items-center">
                    {url === '#' || !url ? (
                        <div className="flex flex-col items-center justify-center text-gray-400">
                            <svg className="w-16 h-16 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
                            <p>No document attached.</p>
                        </div>
                    ) : isImage ? (
                        <img src={url} alt="CV Preview" className="max-w-full max-h-full object-contain shadow-lg" />
                    ) : (
                        // Use object tag for PDF which is more robust than iframe for base64 data
                        <object data={url} type="application/pdf" className="w-full h-full rounded-md bg-white shadow-lg border border-gray-200">
                            <div className="flex flex-col items-center justify-center h-full text-gray-500">
                                <p className="mb-2">Unable to display PDF directly.</p>
                                <a href={url} download className="text-[#1172BA] underline font-bold">Download File</a>
                            </div>
                        </object>
                    )}
                </div>
            </div>
        </div>
    );
};

const ApplicantTracker: React.FC<ApplicantTrackerProps> = ({ vacancy, onBack }) => {
    const [applicants, setApplicants] = useState<Applicant[]>([]);
    const [loading, setLoading] = useState(true);
    const [previewDoc, setPreviewDoc] = useState<{ url: string, name: string } | null>(null);
    const { addToast } = useToast();

    useEffect(() => {
        const fetchApplicants = async () => {
            try {
                setLoading(true);
                // This now pulls freshly from local storage if API fails
                const data = await getApplicantsByVacancy(vacancy.id);
                setApplicants(data);
            } catch (error) {
                addToast('Failed to fetch applicants.', 'error');
            } finally {
                setLoading(false);
            }
        };
        fetchApplicants();
    }, [vacancy.id, addToast]);

    const handleStatusChange = async (applicantId: string, newStatus: ApplicantStatus) => {
        try {
            const updatedApplicant = await updateApplicantStatus(applicantId, newStatus);
            setApplicants(prev => prev.map(app => app.id === applicantId ? updatedApplicant : app));
            addToast(`Status for ${updatedApplicant.name} updated.`, 'success');
        } catch (error) {
            addToast('Failed to update status.', 'error');
        }
    };

    const tableHeaders = ['Applicant', 'Applied Date', 'Status', 'Rating', 'CV / Resume', 'Actions'];

    return (
        <>
            {previewDoc && (
                <DocumentPreviewModal 
                    url={previewDoc.url} 
                    title={`${previewDoc.name}'s Resume`} 
                    onClose={() => setPreviewDoc(null)} 
                />
            )}

            <Card>
                <div className="flex items-center mb-6">
                    <Button variant="icon" onClick={onBack} className="mr-4 hover:bg-gray-100 rounded-full p-2">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                    </Button>
                    <div>
                        <h2 className="text-xl font-bold text-[#1E2B2B] font-montserrat">Applicant Tracker</h2>
                        <p className="text-sm text-gray-500 font-roboto-condensed">Position: <span className="font-semibold text-[#1172BA]">{vacancy.title}</span></p>
                    </div>
                    <div className="ml-auto">
                        <Button variant="secondary" size="sm" onClick={() => { setLoading(true); getApplicantsByVacancy(vacancy.id).then(setApplicants).finally(() => setLoading(false)); }}>
                            Refresh List
                        </Button>
                    </div>
                </div>

                {loading ? (
                    <div className="text-center p-8 text-gray-500">Loading applicants data...</div>
                ) : applicants.length === 0 ? (
                    <div className="text-center p-12 bg-gray-50 rounded-lg border border-gray-100">
                        <svg className="w-12 h-12 mx-auto text-gray-300 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M15 21v-2a4 4 0 00-4-4H9.88a4 4 0 00-3.906 3.012A2.25 2.25 0 016 17v4m6-14v2a2 2 0 002 2h2a2 2 0 002-2v-2"></path></svg>
                        <p className="text-gray-500 font-medium">No applicants found for this vacancy.</p>
                        <p className="text-xs text-gray-400 mt-1">Vacancy ID: {vacancy.id}</p>
                    </div>
                ) : (
                <Table headers={tableHeaders}>
                    {applicants.map(applicant => (
                        <tr key={applicant.id} className="odd:bg-white even:bg-[#effefb] hover:bg-gray-50 transition-colors">
                            <td className="px-6 py-4 whitespace-nowrap">
                                <div className="font-bold text-[#1E2B2B]">{applicant.name}</div>
                                <div className="text-xs text-gray-500">{applicant.email}</div>
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-700 font-mono">
                                {new Date(applicant.appliedDate).toLocaleDateString()}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap">
                               <select 
                                    value={applicant.status}
                                    onChange={(e) => handleStatusChange(applicant.id, e.target.value as ApplicantStatus)}
                                    className={`text-xs font-bold uppercase py-1 px-2 rounded-md border-0 focus:ring-2 focus:ring-[#1172BA] cursor-pointer ${
                                        applicant.status === 'New' ? 'bg-brand-blue-100 text-brand-blue-800' :
                                        applicant.status === 'Hired' ? 'bg-brand-blue-500 text-white' :
                                        applicant.status === 'Rejected' ? 'bg-gray-200 text-gray-600' :
                                        'bg-white border border-gray-300 text-gray-800'
                                    }`}
                               >
                                   <option value="New">New</option>
                                   <option value="Reviewed">Reviewed</option>
                                   <option value="Interview">Interview</option>
                                   <option value="Hired">Hired</option>
                                   <option value="Rejected">Rejected</option>
                               </select>
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap">
                                <StarRating rating={applicant.rating} />
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap">
                                <div className="flex items-center gap-3">
                                    <button 
                                        onClick={() => setPreviewDoc({ url: applicant.cvUrl, name: applicant.name })}
                                        className="flex items-center gap-1 text-[#1172BA] hover:text-[#0E62A1] font-semibold text-sm group px-2 py-1 rounded hover:bg-gray-100 transition-colors"
