import React from 'react';
// FIX: Add import for `types.ts` to ensure global JSX namespace augmentation is applied correctly, resolving errors where standard HTML elements were not recognized in JSX.
import '../types';

// Custom hook to detect when an element is in the viewport
export const useInView = (options: IntersectionObserverInit) => {
  const ref = React.useRef<HTMLDivElement>(null);
  const [isInView, setIsInView] = React.useState(false);

  React.useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        setIsInView(true);
        if (ref.current) {
          observer.unobserve(ref.current);
        }
      }
    }, options);

    if (ref.current) {
      observer.observe(ref.current);
    }

    return () => {
      if (ref.current) {
        observer.unobserve(ref.current);
      }
    };
  }, [options]);

  return [ref, isInView];
};

// Component to wrap sections that should animate on scroll
export const AnimatedSection: React.FC<{ children: React.ReactNode; className?: string; delay?: number }> = ({ children, className = '', delay = 0 }) => {
  const [ref, isInView] = useInView({ threshold: 0.1 });

  return (
    <div
      ref={ref as React.RefObject<HTMLDivElement>}
      className={`animate-on-scroll ${className} ${isInView ? 'is-visible' : ''}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {children}
    </div>
  );
};

// Component for the animated number counter
export const AnimatedCounter: React.FC<{ end: number; duration?: number; className?: string; decimals?: number }> = ({ end, duration = 2000, className, decimals = 0 }) => {
  const [count, setCount] = React.useState(0);
  const [ref, isInView] = useInView({ threshold: 0.5 });

  const easeOutCubic = (t: number) => (--t) * t * t + 1;

  React.useEffect(() => {
    let animationFrameId: number;
    if (isInView) {
      const startTime = performance.now();

      const animateCount = (timestamp: number) => {
        const progress = Math.min((timestamp - startTime) / duration, 1);
        const currentCount = easeOutCubic(progress) * end;
        setCount(currentCount);

        if (progress < 1) {
          animationFrameId = requestAnimationFrame(animateCount);
        }
      };
      animationFrameId = requestAnimationFrame(animateCount);
    }
    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [isInView, end, duration]);

  return <span ref={ref as React.RefObject<HTMLSpanElement>} className={className}>{count.toFixed(decimals)}</span>;
};


// Component for the animated SVG checkmark
export const AnimatedCheckmark: React.FC<{ className?: string }> = ({ className }) => {
    const [ref, isInView] = useInView({ threshold: 0.5 });

    return (
        <svg
            ref={ref as any}
            className={`w-5 h-5 text-[#1172BA] mr-3 flex-shrink-0 ${className}`}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
        >
            <path
                className={isInView ? 'animate-draw' : ''}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
                style={{
                    strokeDasharray: 100,
                    strokeDashoffset: isInView ? 0 : 100,
                    transition: 'stroke-dashoffset 1s ease-in-out',
                }}
            />
        </svg>
    );
};

import '../types';
import React from 'react';
import Logo from './Logo';

const EntranceLoader: React.FC<{ onFinished: () => void }> = ({ onFinished }) => {
  const [isFadingOut, setIsFadingOut] = React.useState(false);

  React.useEffect(() => {
    const fadeTimer = setTimeout(() => {
      setIsFadingOut(true);
    }, 2000); // Logo visible for 2 seconds

    const finishTimer = setTimeout(() => {
      onFinished();
    }, 2800); // Fade out duration is 800ms

    return () => {
      clearTimeout(fadeTimer);
      clearTimeout(finishTimer);
    };
  }, [onFinished]);

  return (
    <div className={`fixed inset-0 z-[100] flex items-center justify-center bg-brand-blue-900 transition-opacity duration-800 ease-in-out ${isFadingOut ? 'opacity-0' : 'opacity-100'}`}>
      <div style={{ animation: 'loader-pulse 2s infinite ease-in-out' }}>
        <Logo className="w-32 h-32" textClassName="text-6xl font-black text-white ml-6" />
      </div>
    </div>
  );
};

export default EntranceLoader;

// FIX: Moved React import to the top of the file before other imports. This ensures that the base JSX namespace is established before any augmentations, resolving errors where standard HTML elements were not recognized in JSX.
import * as React from 'react';
// FIX: Add import for `types.ts` to ensure global JSX namespace augmentation is applied correctly, resolving errors where standard HTML elements were not recognized in JSX.
import '../../../types';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    children: React.ReactNode;
    variant?: 'primary' | 'secondary' | 'icon';
    size?: 'sm' | 'md' | 'lg';
}

const Button: React.FC<ButtonProps> = ({ children, variant = 'primary', size = 'md', className = '', ...props }) => {
    const baseStyles = 'inline-flex items-center justify-center font-semibold rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white transition-all duration-200';

    const variantStyles = {
        // Primary: Base #1172BA, Hover #0E62A1, Focus #1172BA
        primary: 'bg-[#1172BA] text-white hover:bg-[#0E62A1] active:bg-[#04253D] focus:ring-[#1172BA] shadow-sm',
        // Secondary: Base Border Blue, Text Blue, Hover Light Blue
        secondary: 'bg-white text-[#1172BA] border border-[#1172BA] hover:bg-[#F0F7FC] focus:ring-[#1172BA]',
        icon: 'text-gray-500 hover:bg-gray-100 hover:text-[#1172BA] focus:ring-[#1172BA]',
    };

    const sizeStyles = {
        sm: `px-2 py-1 text-xs ${variant === 'icon' ? 'p-1.5' : ''}`,
        md: `px-4 py-2 text-sm ${variant === 'icon' ? 'p-2' : ''}`,
        lg: `px-6 py-3 text-base ${variant === 'icon' ? 'p-3' : ''}`,
    };

    const combinedClassName = `${baseStyles} ${variantStyles[variant]} ${sizeStyles[size]} ${className}`;

    return (
        <button className={combinedClassName} {...props}>
            {children}
        </button>
    );
};

export default Button;

