interface AdminDashboardProps {
    onNavigate: (section: AdminPanelSection) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onNavigate }) => {
    const [stats, setStats] = React.useState<any>(null);
    const [loading, setLoading] = React.useState(true);
    const { addToast } = useToast();

    const fetchStats = async () => {
        setLoading(true);
        try {
            const data = await getDashboardStats();
            setStats(data);
        } catch (err: any) {
            console.error(err);
            addToast('Failed to refresh data', 'error');
        } finally {
            setLoading(false);
        }
    };

    React.useEffect(() => {
        fetchStats();
    }, []);

    const handleDownloadReport = () => {
        addToast('Generating system report...', 'success');

        try {
            // Create content with fallbacks
            const reportContent = `
DEIG SYSTEM REPORT
Generated: ${new Date().toLocaleString()}
-----------------------------------
Total Visitors: ${stats?.visitors || 0}
Active Users: ${stats?.activeUsers || 0}
Open Vacancies: ${stats?.openVacancies || 0}
Unread Inquiries: ${stats?.unreadMessages || 0}
-----------------------------------
System Status: HEALTHY
            `;

            // Create blob and trigger download
            const blob = new Blob([reportContent], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `DEIG_Report_${new Date().toISOString().split('T')[0]}.txt`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        } catch (error) {
            console.error('Download failed:', error);
            addToast('Failed to download report', 'error');
        }
    };

    if (loading && !stats) return <div className="p-8 text-center text-gray-500">Loading Analytics...</div>;

    // Fallback if initial load fails completely
    if (!stats) return <div className="p-8 text-center text-red-500">Failed to load dashboard data. <button onClick={fetchStats} className="underline">Retry</button></div>;

    const recentActivities = stats.recentActivity || [];

    const quickActions = [
        { label: 'Post News', icon: 'M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z', target: 'News Management' },
        { label: 'Add User', icon: 'M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z', target: 'User Management' },
        { label: 'Upload Media', icon: 'M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z', target: 'Media Manager' },
        { label: 'Settings', icon: 'M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37.996.608 2.296.07 2.572-1.065z', target: 'System Settings' },
    ];

    return (
        <div className="space-y-8 animate-fade-in">
            {/* Header Area */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-2xl font-black text-[#1172BA] font-montserrat">Dashboard Overview</h2>
                    <p className="text-gray-500 text-sm">Welcome back, here's what's happening at DEIG.</p>
                </div>
                <div className="flex gap-2">
                    <button 
                        onClick={handleDownloadReport}
                        className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-md text-sm font-semibold hover:bg-gray-50 shadow-sm transition-all"
                    >
                        Download Report
                    </button>
                    <button 
                        onClick={fetchStats}
                        className="bg-[#1172BA] text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-[#0E62A1] shadow-sm transition-all flex items-center gap-2"
                        disabled={loading}
                    >
                       {loading && <svg className="animate-spin h-4 w-4 text-white" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>}
                       {loading ? 'Refreshing...' : 'Refresh Data'}
                    </button>
                </div>
            </div>

            {/* KPI Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <KPIStatCard 
                    title="Total Visitors" 
                    value={stats.visitors.toLocaleString()} 
                    icon={<svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>}
                    trend="12.5%"
                    trendUp={true}
                />
                <KPIStatCard 
                    title="Active Users" 
                    value={stats.activeUsers.toString()} 
                    icon={<svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M15 21v-2a4 4 0 00-4-4H9.88a4 4 0 00-3.906 3.012A2.25 2.25 0 016 17v4m6-14v2a2 2 0 002 2h2a2 2 0 002-2v-2" /></svg>}
                />
                <KPIStatCard 
                    title="Open Vacancies" 
                    value={stats.openVacancies.toString()} 
                    icon={<svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>}
                    trend="2"
                    trendUp={true}
                />
                <KPIStatCard 
                    title="Unread Inquiries" 
                    value={stats.unreadMessages.toString()} 
                    icon={<svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>}
                    trend="5"
                    trendUp={false}
                />
            </div>

            {/* Main Content Area */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
