const NewsPage: React.FC = () => {
    const { t } = useLanguage();
    const [articles, setArticles] = React.useState<NewsArticle[]>([]);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [searchTerm, setSearchTerm] = React.useState('');
    const [selectedCategory, setSelectedCategory] = React.useState<NewsCategory | 'All'>('All');

    React.useEffect(() => {
        const fetchNewsData = async () => {
            try {
                setLoading(true);
                const data = await getNews();
                setArticles(data);
            } catch (err) {
                setError('Failed to load news articles.');
            } finally {
                setLoading(false);
            }
        };
        fetchNewsData();
    }, []);

    const filteredArticles = React.useMemo(() => {
        return articles.filter(article => {
            const matchesCategory = selectedCategory === 'All' || article.category === selectedCategory;
            const matchesSearch = searchTerm === '' ||
                article.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                article.excerpt.toLowerCase().includes(searchTerm.toLowerCase());
            return matchesCategory && matchesSearch;
        });
    }, [articles, searchTerm, selectedCategory]);

    // Get top 5 articles for the slider
    const featuredArticles = articles.slice(0, 5);
    const pressReleases = articles.filter(a => a.category === 'Press Release').slice(0, 4);

    return (
        <div className="bg-transparent">
            {loading ? <div className="py-20 flex justify-center"><Loader /></div> :
             error ? <p className="py-20 text-center text-red-400">{error}</p> :
             <>
                {/* Featured News Slider acting as Hero Section */}
                <FeaturedNewsSlider articles={featuredArticles} />

                <Section id="latest-news-feed" title={t('newsPage.latestNewsTitle', 'Latest News Feed')} className="bg-[#0E62A1]">
                    <div className="max-w-7xl mx-auto">
                        {/* Filters and Search */}
                        <AnimatedSection>
                            <div className="flex flex-col md:flex-row gap-4 justify-between items-center mb-8">
                                <div className="flex-grow w-full md:w-auto">
                                    <input 
                                        type="search" 
                                        value={searchTerm}
                                        onChange={(e) => setSearchTerm(e.target.value)}
                                        placeholder={t('newsPage.searchPlaceholder', 'Search news articles...')}
                                        className="w-full bg-[#1172BA] border border-white/20 rounded-md py-2 px-4 text-white placeholder-white/50 focus:outline-none focus:border-white focus:ring-1 focus:ring-white"
                                    />
                                </div>
                                 <div className="flex items-center space-x-2 overflow-x-auto pb-2">
                                    <button onClick={() => setSelectedCategory('All')} className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-colors whitespace-nowrap ${selectedCategory === 'All' ? 'bg-white text-[#1172BA]' : 'bg-[#1172BA] text-white hover:bg-white/10'}`}>{t('newsPage.allCategories', 'All')}</button>
                                    {categories.map(cat => (
                                         <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-colors whitespace-nowrap ${selectedCategory === cat ? 'bg-white text-[#1172BA]' : 'bg-[#1172BA] text-white hover:bg-white/10'}`}>{cat}</button>
                                    ))}
                                </div>
                            </div>
                        </AnimatedSection>

                        {/* News Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {filteredArticles.length > 0 ? (
                                filteredArticles.map((article, index) => (
                                    <AnimatedSection key={article.id} delay={index * 100}>
                                        <NewsCard article={article} />
                                    </AnimatedSection>
                                ))
                            ) : (
                                <div className="md:col-span-2 lg:col-span-3 text-center py-16 bg-[#1172BA] rounded-md border border-white/20">
                                    <h3 className="text-2xl font-bold text-white font-montserrat">{t('newsPage.noArticles', 'No Articles Found')}</h3>
                                    <p className="mt-2 text-white/80 font-lato">{t('newsPage.noArticlesDesc', 'There are no news articles matching your search or filter criteria. Please try again.')}</p>
                                </div>
                            )}
                        </div>
                    </div>
                </Section>

                <Section id="press-releases" title={t('newsPage.pressReleasesTitle', 'Official Press Releases')} subtitle={t('newsPage.pressReleasesSubtitle', 'Formal statements and announcements from the DEIG corporate office.')} className="bg-[#1172BA]">
                    <div className="max-w-4xl mx-auto bg-[#0E62A1] rounded-md shadow-lg p-2 border border-white/10">
                        {pressReleases.map((article, index) => (
                            <AnimatedSection key={article.id} delay={index * 100}>
                                <PressReleaseItem article={article} />
                            </AnimatedSection>
                        ))}
                    </div>
                </Section>

                 <Section id="events-media" title={t('newsPage.eventsTitle', 'Events & Media Coverage')} subtitle={t('newsPage.eventsSubtitle', "Find out where we've been and what's next on our agenda.")} className="bg-[#0E62A1]">
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-5xl mx-auto">
                        <AnimatedSection>
                            <EventCard titleKey="newsPage.event1_title" descKey="newsPage.event1_desc" image="https://images.pexels.com/photos/1637436/pexels-photo-1637436.jpeg" />
                        </AnimatedSection>
                        <AnimatedSection delay={150}>
                             <EventCard titleKey="newsPage.event2_title" descKey="newsPage.event2_desc" image="https://images.pexels.com/photos/3861958/pexels-photo-3861958.jpeg" />
                        </AnimatedSection>
                     </div>
                </Section>

                <Section id="media-gallery" title={t('newsPage.galleryTitle', 'Media Gallery')} subtitle={t('newsPage.gallerySubtitle', 'A glimpse into our operations, events, and achievements.')} className="bg-[#1172BA]">
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {GALLERY_ITEMS.slice(0, 8).map((item, index) => (
                            <AnimatedSection key={item.id} delay={index * 100}>
                                <div className="group relative aspect-video rounded-md shadow-lg overflow-hidden image-container">
                                    <img src={item.imageUrl} alt={t(item.titleKey)} className="w-full h-full object-cover"/>
                                </div>
                            </AnimatedSection>
                        ))}
                    </div>
                </Section>

                <Section id="newsletter" title={t('newsPage.newsletterTitle', 'Stay Updated')} subtitle={t('newsPage.newsletterSubtitle', 'Subscribe to our newsletter to receive the latest news and updates directly in your inbox.')} className="bg-[#0E62A1]">
                    <AnimatedSection>
                        <form className="max-w-xl mx-auto flex flex-col sm:flex-row gap-4" onSubmit={e => e.preventDefault()}>
                            <input type="email" placeholder={t('newsPage.newsletterPlaceholder', 'Enter your email address')} className="flex-grow bg-[#1172BA] border border-white/30 rounded-md py-3 px-4 text-white placeholder-white/60 focus:outline-none focus:border-white focus:ring-1 focus:ring-white" />
                            <button type="submit" className="bg-white hover:bg-gray-100 text-[#1172BA] font-bold py-3 px-6 rounded-md transition-colors font-roboto-condensed">
                                {t('newsPage.newsletterButton', 'Subscribe')}
                            </button>
                        </form>
                    </AnimatedSection>
                </Section>
             </>
            }
        </div>
    );
};

export default NewsPage;

