const OpeningsSection: React.FC<{ onApply: (vacancy: Vacancy) => void }> = ({ onApply }) => {
    const [vacancies, setVacancies] = React.useState<Vacancy[]>([]);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [filters, setFilters] = React.useState({ role: 'All', division: 'All', experienceLevel: 'All' });
    const { t } = useLanguage();

    React.useEffect(() => {
        const fetchVacancies = async () => {
            try { setLoading(true); const data = await getVacancies(); setVacancies(data); } 
            catch (err) { setError('Failed to load vacancies.'); } 
            finally { setLoading(false); }
        };
        fetchVacancies();
    }, []);

    const handleFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const filterOptions = React.useMemo(() => ({
        roles: ['All', ...Array.from(new Set(vacancies.map(v => v.role)))],
        divisions: ['All', ...Array.from(new Set(vacancies.map(v => v.division)))],
        experienceLevels: ['All', ...Array.from(new Set(vacancies.map(v => v.experienceLevel)))],
    }), [vacancies]);

    const filteredVacancies = React.useMemo(() => vacancies.filter(v => 
        (filters.role === 'All' || v.role === filters.role) &&
        (filters.division === 'All' || v.division === filters.division) &&
        (filters.experienceLevel === 'All' || v.experienceLevel === filters.experienceLevel)
    ), [vacancies, filters]);

    const VacancyCard: React.FC<{ vacancy: Vacancy }> = ({ vacancy }) => (
        <div className="bg-white p-6 rounded-md shadow-lg card-hover-effect flex flex-col h-full text-[#1172BA] border-2 border-transparent hover:border-[#1172BA]">
          <div>
              <h3 className="text-xl font-bold text-[#1172BA] font-roboto-condensed card-title">{vacancy.title}</h3>
              <p className="text-gray-600 font-semibold font-roboto-condensed">{vacancy.location}</p>
              <div className="flex flex-wrap gap-2 mt-3 text-xs font-semibold">
                  <span className="bg-blue-50 text-[#1172BA] px-2 py-1 rounded-full">{vacancy.division}</span>
                  <span className="bg-blue-50 text-[#1172BA] px-2 py-1 rounded-full">{vacancy.role}</span>
                  <span className="bg-blue-50 text-[#1172BA] px-2 py-1 rounded-full">{vacancy.experienceLevel}</span>
              </div>
          </div>
          <p className="mt-4 text-gray-700 font-lato flex-grow line-clamp-3">{vacancy.description}</p>
          <button onClick={() => onApply(vacancy)} className="mt-6 bg-[#1172BA] hover:bg-[#0E62A1] text-white font-bold py-2 px-4 rounded-md transition-colors duration-300 font-roboto-condensed self-start">
            {t('vacancyPage.applyNow')}
          </button>
        </div>
    );

    return (
        <>
            <AnimatedSection>
                <div className="bg-[#0E62A1] p-4 rounded-md mb-12 grid grid-cols-1 md:grid-cols-4 gap-4 items-center">
                    <h3 className="text-lg font-bold text-white font-roboto-condensed md:text-right">{t('vacancyPage.filterBy')}</h3>
                    <select name="role" value={filters.role} onChange={handleFilterChange} className="bg-[#1172BA] border border-white/20 text-white text-sm rounded-md focus:ring-white focus:border-white w-full p-2">
                        {filterOptions.roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                    <select name="division" value={filters.division} onChange={handleFilterChange} className="bg-[#1172BA] border border-white/20 text-white text-sm rounded-md focus:ring-white focus:border-white w-full p-2">
                        {filterOptions.divisions.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                    <select name="experienceLevel" value={filters.experienceLevel} onChange={handleFilterChange} className="bg-[#1172BA] border border-white/20 text-white text-sm rounded-md focus:ring-white focus:border-white w-full p-2">
                        {filterOptions.experienceLevels.map(e => <option key={e} value={e}>{e}</option>)}
                    </select>
                </div>
            </AnimatedSection>
            <div className="space-y-8">
                {loading ? <div className="flex justify-center"><Loader /></div> :
                 error ? <p className="text-center text-red-400">{error}</p> :
                 filteredVacancies.length > 0 ? (
                    filteredVacancies.map((vacancy, index) => (
                        <AnimatedSection key={vacancy.id} delay={index * 100}>
                            <VacancyCard vacancy={vacancy} />
                        </AnimatedSection>
                    ))
                 ) : (
                    <AnimatedSection>
                        <div className="text-center py-16 bg-[#0E62A1]/50 rounded-md border border-white/10">
                            <h3 className="text-2xl font-bold text-white font-montserrat">{t('vacancyPage.noOpenings')}</h3>
                            <p className="mt-2 text-white/80 font-lato">{t('vacancyPage.noOpeningsDesc')}</p>
                        </div>
                    </AnimatedSection>
                 )}
            </div>
        </>
    );
};

