const JobDetailModal: React.FC<{ vacancy: Vacancy; onClose: () => void; }> = ({ vacancy, onClose }) => {
    const { t } = useLanguage();
    const { addToast } = useToast();
    const [isSubmitting, setIsSubmitting] = React.useState(false);
    const modalRef = React.useRef<HTMLDivElement>(null);

    React.useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        document.addEventListener('keydown', handleKeyDown);
        return () => document.removeEventListener('keydown', handleKeyDown);
    }, [onClose]);

    const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
        if (modalRef.current && !modalRef.current.contains(e.target as Node)) {
            onClose();
        }
    };

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setIsSubmitting(true);
        const formData = new FormData(e.currentTarget);
        formData.append('vacancyId', vacancy.id);

        try {
            await createApplicant(formData);
            addToast(`Application for ${vacancy.title} submitted successfully!`, 'success');
            onClose();
        } catch (error) {
            console.error('Application submission failed:', error);
            addToast('Failed to submit application. Please try again.', 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div 
            className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center p-4 animate-fade-in"
            onClick={handleBackdropClick}
        >
            <div ref={modalRef} className="relative bg-white text-[#1172BA] rounded-lg shadow-xl w-full max-w-3xl max-h-[90vh] flex flex-col">
                <div className="flex justify-between items-center p-6 border-b border-gray-200">
                    <div>
                        <h2 className="text-2xl font-bold text-[#1172BA] font-montserrat">{vacancy.title}</h2>
                        <p className="text-gray-600 font-semibold font-roboto-condensed">{vacancy.location} • {vacancy.type}</p>
                    </div>
                    <button onClick={onClose} className="p-2 rounded-full text-gray-500 hover:bg-gray-100" aria-label="Close">
                         <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                    </button>
                </div>
                <div className="overflow-y-auto p-6 space-y-6">
                    <div>
                        <h3 className="text-lg font-bold font-roboto-condensed mb-2 text-[#1172BA]">{t('vacancyPage.modal.responsibilities')}</h3>
                        <ul className="list-disc list-inside space-y-1 text-gray-700 font-lato">
                            {vacancy.responsibilities.map((item, i) => <li key={i}>{item}</li>)}
                        </ul>
                    </div>
                     <div>
                        <h3 className="text-lg font-bold font-roboto-condensed mb-2 text-[#1172BA]">{t('vacancyPage.modal.requirements')}</h3>
                        <ul className="list-disc list-inside space-y-1 text-gray-700 font-lato">
                             {vacancy.requirements.map((item, i) => <li key={i}>{item}</li>)}
                        </ul>
                    </div>
                     <div>
                        <h3 className="text-lg font-bold font-roboto-condensed mb-2 text-[#1172BA]">{t('vacancyPage.modal.applyTitle')}</h3>
                        <form onSubmit={handleSubmit} className="space-y-4 bg-gray-50 p-4 rounded-md border border-gray-200">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label htmlFor="name" className="block text-sm font-medium text-gray-700">{t('vacancyPage.cv.name')}</label>
                                    <input type="text" id="name" name="name" required className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#1172BA] focus:border-[#1172BA]" />
                                </div>
                                <div>
                                    <label htmlFor="email" className="block text-sm font-medium text-gray-700">{t('vacancyPage.cv.email')}</label>
                                    <input type="email" id="email" name="email" required className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-[#1172BA] focus:border-[#1172BA]" />
                                </div>
                            </div>
                            <div>
                                <label htmlFor="cv-upload" className="block text-sm font-medium text-gray-700">{t('vacancyPage.cv.upload')}</label>
                                <input type="file" id="cv-upload" name="cv" required accept=".pdf,.doc,.docx" className="mt-1 block w-full text-sm text-gray-700 file:mr-4 file:py-2 file:px-4 file:rounded-md file:border-0 file:font-semibold file:bg-[#1172BA] file:text-white hover:file:bg-[#0E62A1]"/>
                            </div>
                            <button type="submit" disabled={isSubmitting} className="w-full bg-[#1172BA] hover:bg-[#0E62A1] text-white font-bold py-2 px-4 rounded-md disabled:opacity-50 disabled:cursor-not-allowed">
                                {isSubmitting ? 'Submitting...' : t('vacancyPage.cv.submit')}
                            </button>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
};


const OpeningsSection: React.FC<{ onApply: (vacancy: Vacancy) => void }> = ({ onApply }) => {
    const [vacancies, setVacancies] = React.useState<Vacancy[]>([]);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [filters, setFilters] = React.useState({ role: 'All', division: 'All', experienceLevel: 'All' });
    const { t } = useLanguage();

    React.useEffect(() => {
        const fetchVacancies = async () => {
            try { setLoading(true); const data = await getVacancies(); setVacancies(data); } 
            catch (err) { setError('Failed to load vacancies.'); } 
            finally { setLoading(false); }
        };
        fetchVacancies();
    }, []);

    const handleFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const filterOptions = React.useMemo(() => ({
        roles: ['All', ...Array.from(new Set(vacancies.map(v => v.role)))],
        divisions: ['All', ...Array.from(new Set(vacancies.map(v => v.division)))],
        experienceLevels: ['All', ...Array.from(new Set(vacancies.map(v => v.experienceLevel)))],
    }), [vacancies]);

    const filteredVacancies = React.useMemo(() => vacancies.filter(v => 
        (filters.role === 'All' || v.role === filters.role) &&
        (filters.division === 'All' || v.division === filters.division) &&
        (filters.experienceLevel === 'All' || v.experienceLevel === filters.experienceLevel)
    ), [vacancies, filters]);

    const VacancyCard: React.FC<{ vacancy: Vacancy }> = ({ vacancy }) => (
        <div className="bg-white p-6 rounded-md shadow-lg card-hover-effect flex flex-col h-full text-[#1172BA] border border-gray-200 hover:border-[#1172BA]">
          <div>
              <h3 className="text-xl font-bold text-[#1172BA] font-roboto-condensed card-title">{vacancy.title}</h3>
              <p className="text-gray-600 font-semibold font-roboto-condensed">{vacancy.location}</p>
              <div className="flex flex-wrap gap-2 mt-3 text-xs font-semibold">
                  <span className="bg-blue-50 text-[#1172BA] px-2 py-1 rounded-full">{vacancy.division}</span>
                  <span className="bg-blue-50 text-[#1172BA] px-2 py-1 rounded-full">{vacancy.role}</span>
                  <span className="bg-blue-50 text-[#1172BA] px-2 py-1 rounded-full">{vacancy.experienceLevel}</span>
              </div>
          </div>
          <p className="mt-4 text-gray-700 font-lato flex-grow line-clamp-3">{vacancy.description}</p>
          <button onClick={() => onApply(vacancy)} className="mt-6 bg-[#1172BA] hover:bg-[#0E62A1] text-white font-bold py-2 px-4 rounded-md transition-colors duration-300 font-roboto-condensed self-start">
            {t('vacancyPage.applyNow')}
          </button>
        </div>
    );

    return (
        <>
            <AnimatedSection>
                <div className="bg-white border border-gray-200 p-4 rounded-md mb-12 grid grid-cols-1 md:grid-cols-4 gap-4 items-center shadow-sm">
                    <h3 className="text-lg font-bold text-[#1172BA] font-roboto-condensed md:text-right">{t('vacancyPage.filterBy')}</h3>
                    <select name="role" value={filters.role} onChange={handleFilterChange} className="bg-gray-50 border border-gray-300 text-gray-700 text-sm rounded-md focus:ring-[#1172BA] focus:border-[#1172BA] w-full p-2">
                        {filterOptions.roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                    <select name="division" value={filters.division} onChange={handleFilterChange} className="bg-gray-50 border border-gray-300 text-gray-700 text-sm rounded-md focus:ring-[#1172BA] focus:border-[#1172BA] w-full p-2">
                        {filterOptions.divisions.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                    <select name="experienceLevel" value={filters.experienceLevel} onChange={handleFilterChange} className="bg-gray-50 border border-gray-300 text-gray-700 text-sm rounded-md focus:ring-[#1172BA] focus:border-[#1172BA] w-full p-2">
                        {filterOptions.experienceLevels.map(e => <option key={e} value={e}>{e}</option>)}
                    </select>
                </div>
            </AnimatedSection>
            <div className="space-y-8">
                {loading ? <div className="flex justify-center"><Loader /></div> :
                 error ? <p className="text-center text-red-400">{error}</p> :
                 filteredVacancies.length > 0 ? (
                    filteredVacancies.map((vacancy, index) => (
                        <AnimatedSection key={vacancy.id} delay={index * 100}>
                            <VacancyCard vacancy={vacancy} />
                        </AnimatedSection>
                    ))
                 ) : (
                    <AnimatedSection>
                        <div className="text-center py-16 bg-white rounded-md border border-gray-200">
                            <h3 className="text-2xl font-bold text-[#1172BA] font-montserrat">{t('vacancyPage.noOpenings')}</h3>
                            <p className="mt-2 text-gray-600 font-lato">{t('vacancyPage.noOpeningsDesc')}</p>
                        </div>
                    </AnimatedSection>
                 )}
            </div>
        </>
    );
};

