                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="group">
                        <label htmlFor="name" className="block text-sm font-medium text-gray-700 dark:text-white/90 mb-1 transition-colors group-focus-within:text-[#1172BA] dark:group-focus-within:text-white">{t('contactPage.form.name')}</label>
                        <input type="text" id="name" name="name" className="w-full bg-gray-50 dark:bg-white/10 border border-gray-300 dark:border-white/20 rounded-lg py-3 px-4 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#1172BA] dark:focus:ring-white focus:border-transparent transition-shadow" required placeholder="John Doe" />
                    </div>
                    <div className="group">
                        <label htmlFor="email" className="block text-sm font-medium text-gray-700 dark:text-white/90 mb-1 transition-colors group-focus-within:text-[#1172BA] dark:group-focus-within:text-white">{t('contactPage.form.email')}</label>
                        <input type="email" id="email" name="email" className="w-full bg-gray-50 dark:bg-white/10 border border-gray-300 dark:border-white/20 rounded-lg py-3 px-4 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#1172BA] dark:focus:ring-white focus:border-transparent transition-shadow" required placeholder="john@example.com" />
                    </div>
                </div>
                 <div className="group">
                    <label htmlFor="department" className="block text-sm font-medium text-gray-700 dark:text-white/90 mb-1 transition-colors group-focus-within:text-[#1172BA] dark:group-focus-within:text-white">{t('contactPage.form.department')}</label>
                    <div className="relative">
                        <select id="department" name="department" className="w-full bg-gray-50 dark:bg-white/10 border border-gray-300 dark:border-white/20 rounded-lg py-3 px-4 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#1172BA] dark:focus:ring-white focus:border-transparent appearance-none transition-shadow">
                            {departments.map(dept => <option key={dept} value={dept} className="text-gray-900">{t(`contactPage.form.depts.${dept}`)}</option>)}
                        </select>
                        <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-gray-500 dark:text-white/70">
                            <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                        </div>
                    </div>
                </div>
                <div className="group">
                    <label htmlFor="subject" className="block text-sm font-medium text-gray-700 dark:text-white/90 mb-1 transition-colors group-focus-within:text-[#1172BA] dark:group-focus-within:text-white">{t('contactPage.form.subject')}</label>
                    <input type="text" id="subject" name="subject" className="w-full bg-gray-50 dark:bg-white/10 border border-gray-300 dark:border-white/20 rounded-lg py-3 px-4 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#1172BA] dark:focus:ring-white focus:border-transparent transition-shadow" required placeholder="Brief summary of your inquiry" />
