            const expiresIn = process.env.JWT_EXPIRES_IN || '30d';

            const token = jwt.sign(payload, secret, {
                expiresIn: expiresIn,
            });

            res.json({
                message: 'Login successful',
                token,
                user: {
                    id: user.id,
                    name: user.name,
                    email: user.email,
                    role: user.Role ? user.Role.name : 'Viewer',
