                    {t('newsPage.backButton', 'Back to News')}
                </Link>
            </div>
        );
    }

    // Use content if available, otherwise fall back to excerpt, otherwise standard placeholder
    const displayContent = article.content || article.excerpt;

    return (
        <div className="bg-gray-50 dark:bg-brand-blue-900 min-h-screen">
            {/* Hero Image Section */}
            <div className="w-full h-[50vh] md:h-[60vh] relative">
                <img src={article.imageUrl} alt={article.title} className="w-full h-full object-cover" />
