// Helper to convert File to Base64 Data URL
const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
    });
};

// --- API HELPER ---
const apiHelper = async (endpoint: string, options: RequestInit = {}) => {
    const token = localStorage.getItem('deig-admin-token');
    const headers = { ...options.headers };

    if (token) {
        (headers as Record<string, string>)['Authorization'] = `Bearer ${token}`;
    }

    if (!(options.body instanceof FormData)) {
        (headers as Record<string, string>)['Content-Type'] = 'application/json';
    }

    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000); // Increased timeout to 5s

        const response = await fetch(`${API_BASE_URL}${endpoint}`, {
            ...options,
            headers,
            signal: controller.signal
        });

        clearTimeout(timeoutId);

        if (response.status === 401) {
            // Token is invalid or expired. Clear it and redirect.
            console.error("Unauthorized (401). Clearing invalid token.");
            localStorage.removeItem('deig-admin-token');
            localStorage.removeItem('deig-admin-user');

            // Only redirect if explicitly on a protected admin route, otherwise just fail the call
            if (window.location.hash.includes('admin')) {
                window.location.href = '/#/login';
            }
            throw new Error('Session expired. Please login again.');
        }

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({ message: 'An unknown error occurred' }));
            throw new Error(errorData.message || `API error: ${response.statusText}`);
        }

        if (response.status === 204) return null;
        return response.json();
    } catch (error: any) {
        // If it's a connection error (backend down), we might want to fallback to mock data
        if (error.message === 'Session expired. Please login again.') {
            throw error;
        }

        console.warn(`API Call Failed to ${API_BASE_URL}${endpoint}.`, error);
        throw error; // Re-throw to let components handle it or fallback explicitly
    }
};

// --- AUTH ---
export const login = async (email: string, password: string): Promise<any> => {
    // Attempt real login first
    try {
        return await apiHelper('/auth/login', {
            method: 'POST',
            body: JSON.stringify({ email, password }),
        });
    } catch (error) {
        console.error("Backend login failed:", error);
        throw new Error('Login failed. Please ensure the backend is running and credentials are correct.');
    }
};

