User.hasMany(SecurityLog, { foreignKey: 'userId' });
SecurityLog.belongsTo(User, { foreignKey: 'userId' });

module.exports = {
  sequelize,
  User, Role, Industry, News, Vacancy, Applicant, Media, Page, Inquiry, SecurityLog, Tender
