                        className={`flex-1 py-3 text-sm font-bold text-center transition-colors ${langTab === 'am' ? 'bg-white text-[#1172BA] border-b-2 border-[#1172BA]' : 'bg-gray-50 text-gray-500 hover:bg-gray-100'}`}
