                        {/* Categories and Status are shared */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
                            <select name="category" value={formData.category || ''} onChange={handleChange} className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA]" required>
