                <img src={article.imageUrl} alt={title} loading="lazy" className="w-full h-full object-cover" />
                <span className="absolute top-2 right-2 bg-[#1172BA] text-white text-xs font-bold px-2 py-1 rounded-md font-roboto-condensed">{article.category}</span>
