const NewsPage: React.FC = () => {
    const { t, language } = useLanguage();
    const [articles, setArticles] = React.useState<NewsArticle[]>([]);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const [searchTerm, setSearchTerm] = React.useState('');
    const [selectedCategory, setSelectedCategory] = React.useState<NewsCategory | 'All'>('All');

    React.useEffect(() => {
        const fetchNewsData = async () => {
            try {
                setLoading(true);
                const data = await getNews();
                setArticles(data);
            } catch (err) {
                setError('Failed to load news articles.');
            } finally {
                setLoading(false);
            }
        };
        fetchNewsData();
    }, []);

    const filteredArticles = React.useMemo(() => {
        return articles.filter(article => {
            const title = (language === 'am' && article.titleAm) ? article.titleAm : article.title;
            const excerpt = (language === 'am' && article.excerptAm) ? article.excerptAm : article.excerpt;

            const matchesCategory = selectedCategory === 'All' || article.category === selectedCategory;
            const matchesSearch = searchTerm === '' ||
                title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                excerpt.toLowerCase().includes(searchTerm.toLowerCase());
            return matchesCategory && matchesSearch;
        });
    }, [articles, searchTerm, selectedCategory, language]);

    // Get top 5 articles for the slider
    const featuredArticles = articles.slice(0, 5);
    const pressReleases = articles.filter(a => a.category === 'Press Release').slice(0, 4);

    return (
        <div className="bg-gray-50">
            {loading ? <div className="py-20 flex justify-center"><Loader /></div> :
             error ? <p className="py-20 text-center text-red-400">{error}</p> :
             <>
                {/* Featured News Slider acting as Hero Section */}
                <FeaturedNewsSlider articles={featuredArticles} />

                <Section id="latest-news-feed" title={t('newsPage.latestNewsTitle', 'Latest News Feed')} className="bg-gray-50" darkText={true}>
                    <div className="max-w-7xl mx-auto">
                        {/* Filters and Search */}
                        <AnimatedSection>
                            <div className="flex flex-col md:flex-row gap-4 justify-between items-center mb-8">
                                <div className="flex-grow w-full md:w-auto">
                                    <input 
                                        type="search" 
                                        value={searchTerm}
                                        onChange={(e) => setSearchTerm(e.target.value)}
                                        placeholder={t('newsPage.searchPlaceholder', 'Search news articles...')}
                                        className="w-full bg-white border border-gray-300 rounded-md py-2 px-4 text-gray-800 placeholder-gray-400 focus:outline-none focus:border-[#1172BA] focus:ring-1 focus:ring-[#1172BA] shadow-sm"
                                    />
                                </div>
                                 <div className="flex items-center space-x-2 overflow-x-auto pb-2">
                                    <button onClick={() => setSelectedCategory('All')} className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-colors whitespace-nowrap shadow-sm border ${selectedCategory === 'All' ? 'bg-[#1172BA] text-white border-[#1172BA]' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}`}>{t('newsPage.allCategories', 'All')}</button>
                                    {categories.map(cat => (
                                         <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-colors whitespace-nowrap shadow-sm border ${selectedCategory === cat ? 'bg-[#1172BA] text-white border-[#1172BA]' : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'}`}>{cat}</button>
                                    ))}
                                </div>
                            </div>
                        </AnimatedSection>

                        {/* News Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {filteredArticles.length > 0 ? (
                                filteredArticles.map((article, index) => (
                                    <AnimatedSection key={article.id} delay={index * 100}>
                                        <NewsCard article={article} />
                                    </AnimatedSection>
                                ))
                            ) : (
                                <div className="md:col-span-2 lg:col-span-3 text-center py-16 bg-white rounded-md border border-gray-200">
                                    <h3 className="text-2xl font-bold text-[#1172BA] font-montserrat">{t('newsPage.noArticles', 'No Articles Found')}</h3>
                                    <p className="mt-2 text-gray-600 font-lato">{t('newsPage.noArticlesDesc', 'There are no news articles matching your search or filter criteria. Please try again.')}</p>
                                </div>
                            )}
                        </div>
                    </div>
                </Section>

                <Section id="press-releases" title={t('newsPage.pressReleasesTitle', 'Official Press Releases')} subtitle={t('newsPage.pressReleasesSubtitle', 'Formal statements and announcements from the DEIG corporate office.')} className="bg-[#F0F7FC]" darkText={true}>
                    <div className="max-w-4xl mx-auto bg-white rounded-md shadow-lg p-2 border border-gray-200">
                        {pressReleases.length > 0 ? (
                            pressReleases.map((article, index) => (
                                <AnimatedSection key={article.id} delay={index * 100}>
                                    <PressReleaseItem article={article} />
                                </AnimatedSection>
                            ))
                        ) : (
                            <p className="text-center py-4 text-gray-500">No recent press releases.</p>
                        )}
                    </div>
                </Section>

                 <Section id="events-media" title={t('newsPage.eventsTitle', 'Events & Media Coverage')} subtitle={t('newsPage.eventsSubtitle', "Find out where we've been and what's next on our agenda.")} className="bg-white" darkText={true}>
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-5xl mx-auto">
                        <AnimatedSection>
                            <EventCard titleKey="newsPage.event1_title" descKey="newsPage.event1_desc" image="https://images.pexels.com/photos/1637436/pexels-photo-1637436.jpeg" />
                        </AnimatedSection>
                        <AnimatedSection delay={150}>
                             <EventCard titleKey="newsPage.event2_title" descKey="newsPage.event2_desc" image="https://images.pexels.com/photos/3861958/pexels-photo-3861958.jpeg" />
                        </AnimatedSection>
                     </div>
                </Section>

                <Section id="media-gallery" title={t('newsPage.galleryTitle', 'Media Gallery')} subtitle={t('newsPage.gallerySubtitle', 'A glimpse into our operations, events, and achievements.')} className="bg-gray-50" darkText={true}>
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {GALLERY_ITEMS.slice(0, 8).map((item, index) => (
                            <AnimatedSection key={item.id} delay={index * 100}>
                                <div className="group relative aspect-video rounded-md shadow-lg overflow-hidden image-container">
                                    <img src={item.imageUrl} alt={t(item.titleKey)} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500"/>
                                </div>
                            </AnimatedSection>
                        ))}
                    </div>
                </Section>

                <Section id="newsletter" title={t('newsPage.newsletterTitle', 'Stay Updated')} subtitle={t('newsPage.newsletterSubtitle', 'Subscribe to our newsletter to receive the latest news and updates directly in your inbox.')} className="bg-[#1172BA]">
                    <AnimatedSection>
                        <form className="max-w-xl mx-auto flex flex-col sm:flex-row gap-4" onSubmit={e => e.preventDefault()}>
                            <input type="email" placeholder={t('newsPage.newsletterPlaceholder', 'Enter your email address')} className="flex-grow bg-white border border-white/30 rounded-md py-3 px-4 text-gray-900 placeholder-gray-500 focus:outline-none focus:border-white focus:ring-2 focus:ring-white/50" />
                            <button type="submit" className="bg-[#0E62A1] hover:bg-[#0A4D7F] text-white border border-white/20 font-bold py-3 px-6 rounded-md transition-colors font-roboto-condensed shadow-lg">
                                {t('newsPage.newsletterButton', 'Subscribe')}
                            </button>
                        </form>
                    </AnimatedSection>
                </Section>
             </>
            }
        </div>
    );
};

export default NewsPage;

import React from 'react';
import '../types';
import { useParams, Link } from 'react-router-dom';
import { getNewsById, getNews } from '../services/api';
import type { NewsArticle } from '../types';
import Loader from '../components/Loader';
import { useLanguage } from '../hooks/useLanguage';
import { AnimatedSection } from '../components/AnimatedComponents';

const NewsDetailPage: React.FC = () => {
    const { id } = useParams();
    const [article, setArticle] = React.useState<NewsArticle | null>(null);
    const [recentNews, setRecentNews] = React.useState<NewsArticle[]>([]);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState<string | null>(null);
    const { t, language } = useLanguage();

    React.useEffect(() => {
        const fetchArticle = async () => {
            if (!id) return;
            try {
                setLoading(true);
                setError(null);

                // Fetch the specific article
                const data = await getNewsById(id);
                if (!data) throw new Error("Article not found");
                setArticle(data);

                // Fetch recent news for sidebar (separate try-catch to not block main content)
                try {
                    const allNews = await getNews();
                    if(allNews && Array.isArray(allNews)) {
                        const others = allNews.filter(a => a.id.toString() !== id).slice(0, 5);
                        setRecentNews(others);
                    }
                } catch (e) {
                    console.warn("Failed to load recent news sidebar", e);
                }

                // Scroll to top
                window.scrollTo(0, 0);
            } catch (err) {
                console.error(err);
                setError('Failed to load article.');
            } finally {
                setLoading(false);
            }
        };
        fetchArticle();
    }, [id]);

    if (loading) {
        return <div className="flex justify-center items-center h-screen bg-gray-50 dark:bg-brand-blue-900"><Loader /></div>;
    }

    if (error || !article) {
        return (
            <div className="container mx-auto px-6 py-20 text-center bg-gray-50 dark:bg-brand-blue-900 min-h-screen">
                <h1 className="text-4xl font-bold text-brand-blue-900 dark:text-white font-montserrat">{t('newsPage.errorTitle', 'Article Not Found')}</h1>
                <p className="mt-4 text-brand-blue-900/80 dark:text-brand-blue-50 font-lato">{t('newsPage.errorText', 'The article you are looking for does not exist or has been removed.')}</p>
                <Link to="/news" className="mt-8 inline-block bg-brand-blue-600 hover:bg-brand-blue-700 text-white font-bold py-3 px-8 rounded-md btn-hover-effect font-roboto-condensed">
                    {t('newsPage.backButton', 'Back to News')}
                </Link>
            </div>
        );
    }

    // Determine content based on language preference (fallback to English if Amharic missing)
    const title = (language === 'am' && article.titleAm) ? article.titleAm : article.title;
    const excerpt = (language === 'am' && article.excerptAm) ? article.excerptAm : article.excerpt;
    // Prefer full content, then excerpt. Check Amharic content first if language is Amharic.
    let displayContent = article.content || article.excerpt;
    if (language === 'am') {
        if (article.contentAm) displayContent = article.contentAm;
        else if (article.excerptAm) displayContent = article.excerptAm;
        // If no Amharic content found, fall back to English default
    }

    return (
        <div className="bg-gray-50 dark:bg-brand-blue-900 min-h-screen">
            {/* Hero Image Section */}
            <div className="w-full h-[50vh] md:h-[60vh] relative">
                <img src={article.imageUrl} alt={title} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-brand-blue-900 to-transparent opacity-80"></div>
                <div className="absolute bottom-0 left-0 right-0 container mx-auto px-6 pb-12">
                    <AnimatedSection>
                        <span className="inline-block bg-brand-blue-600 text-white text-xs font-bold px-3 py-1 rounded-full uppercase tracking-wider mb-4">
                            {article.category}
                        </span>
                        <h1 className="text-3xl md:text-5xl font-black text-white font-montserrat leading-tight shadow-sm max-w-4xl">
                            {title}
                        </h1>
                        <p className="text-white/80 font-roboto-condensed mt-4 text-lg">
                            {new Date(article.date).toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' })}
                        </p>
                    </AnimatedSection>
                </div>
            </div>

            <div className="container mx-auto px-6 py-12">
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                    {/* Main Content Column */}
                    <div className="lg:col-span-2">
                        <AnimatedSection delay={100}>
                            <div className="bg-white dark:bg-brand-blue-800 rounded-lg p-8 shadow-lg">
                                {/* Lead Paragraph / Excerpt (Only if distinct from main content or specifically intended as summary) */}
                                {excerpt && displayContent && (
                                    <p className="text-xl font-bold text-brand-blue-900 dark:text-brand-blue-100 font-lato mb-8 leading-relaxed border-l-4 border-brand-blue-500 pl-4">
                                        {excerpt}
                                    </p>
                                )}

                                {/* Full Rich Content */}
                                <div className="prose dark:prose-invert max-w-none text-justify font-lato text-lg leading-relaxed text-gray-800 dark:text-gray-200">
                                    {displayContent ? (
                                        <div dangerouslySetInnerHTML={{ __html: displayContent }} />
                                    ) : (
                                        // Fallback text if no content provided at all
                                        <div className="space-y-4">
                                            <p>No content available for this article.</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </AnimatedSection>

                        <div className="mt-8 flex justify-between items-center">
                            <Link to="/news" className="text-brand-blue-600 dark:text-brand-blue-300 font-bold hover:underline flex items-center">
                                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                                {t('newsPage.backButton', 'Back to News')}
                            </Link>
                            {/* Share Buttons Placeholder */}
