                            placeholder={langTab === 'en' ? "Brief summary shown on cards..." : "በካርዶች ላይ የሚታይ አጭር መግለጫ..."}
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Cover Image (Shared)</label>
                        <div className="flex gap-4 items-center">
