    React.useEffect(() => {
        const fetchNewsData = async () => {
            try {
                setLoading(true);
                const data = await getNews();
                setArticles(data);
            } catch (err) {
                setError('Failed to load news articles.');
            } finally {
                setLoading(false);
            }
        };
        fetchNewsData();
