    } catch (e) {
        const newTender = { ...data, id: `TEN-LOCAL-${Date.now()}` } as Tender;
        LOCAL_TENDERS = [newTender, ...LOCAL_TENDERS];
        saveToStorage('deig_tenders', LOCAL_TENDERS);
        return newTender;
    }
