    try {
        return await apiHelper('/pages', { method: 'POST', body: JSON.stringify(pageData) });
    } catch (e) {
        const pages = loadFromStorage('deig_pages', PAGES);
        const newPage = { ...pageData, id: `PAGE-LOCAL-${Date.now()}`, lastEdited: new Date().toISOString() } as Page;
