                                    <div className="flex items-center justify-end gap-2">
                                        <select 
                                            className="text-xs border-gray-300 rounded p-1 bg-white"
                                            value={supplier.status}
                                            onChange={(e) => handleStatusChange(supplier.id, e.target.value as SupplierStatus)}
