// --- Toast Notification System ---

interface ToastContextType {
  addToast: (message: string, type: ToastType) => void;
}

const ToastContext = React.createContext<ToastContextType | undefined>(undefined);

export const useToast = () => {
  const context = React.useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
};

const ToastContainer: React.FC<{ toasts: Toast[] }> = ({ toasts }) => (
  <div className="fixed top-4 right-4 z-[200] space-y-2 w-full max-w-xs">
    {toasts.map((toast) => (
      <ToastMessage key={toast.id} toast={toast} />
    ))}
  </div>
);

const ToastMessage: React.FC<{ toast: Toast }> = ({ toast }) => {
  const icons = {
    success: <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>,
    error: <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" /></svg>,
  };

  // Use Brand Blue for Success and White/Gray with Blue Border for Error to stick to #1172BA palette
  const colors = {
    success: 'bg-brand-blue-500 text-white border-brand-blue-600',
    error: 'bg-white border-brand-blue-500 text-brand-blue-900 border-2',
  };

  return (
    <div className={`flex items-start p-4 rounded-md shadow-lg border ${colors[toast.type]} animate-fade-in`}>
      <div className="flex-shrink-0">{icons[toast.type]}</div>
      <div className="ml-3 text-sm font-medium">{toast.message}</div>
    </div>
  );
};

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = React.useState<Toast[]>([]);

  const addToast = React.useCallback((message: string, type: ToastType) => {
    const id = Date.now();
    setToasts((prevToasts) => [...prevToasts, { id, message, type }]);
    setTimeout(() => {
      setToasts((prevToasts) => prevToasts.filter((t) => t.id !== id));
    }, 5000);
  }, []);

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      <ToastContainer toasts={toasts} />
    </ToastContext.Provider>
  );
};


// --- End of Toast System ---


const ScrollToTop: React.FC = () => {
