  }, []);

  const handleLoadingFinished = () => {
    setIsLoading(false);
    sessionStorage.setItem('deig-session-loaded', 'true');
  };

  return (
    <div className="flex flex-col min-h-screen bg-gray-50 dark:bg-brand-blue-900">
