                                name="title" 
                                value={formData.title || ''} 
                                onChange={handleChange} 
                                placeholder="e.g., About Us" 
                                className="w-full border-gray-300 rounded-md p-2.5 focus:ring-[#1172BA] focus:border-[#1172BA]" 
                                required 
                            />
